const updateDeploymentStatus = `-- name: UpdateDeploymentStatus :one
UPDATE deployments SET status = $2, error_message = $3, finished_at = NOW()
WHERE id = $1
RETURNING id, application_id, status, triggered_by, commit_sha, image_tag, build_logs, error_message, started_at, build_started_at, build_ended_at, deploy_started_at, finished_at, idempotency_key, health_status, health_message, health_checked_at
`

type UpdateDeploymentStatusParams struct {
	ID           pgtype.UUID `json:"id"`
	Status       string      `json:"status"`
	ErrorMessage pgtype.Text `json:"error_message"`
}

func (q *Queries) UpdateDeploymentStatus(ctx context.Context, arg UpdateDeploymentStatusParams) (Deployment, error) {
	row := q.db.QueryRow(ctx, updateDeploymentStatus, arg.ID, arg.Status, arg.ErrorMessage)
	var i Deployment
	err := row.Scan(
		&i.ID,
		&i.ApplicationID,
		&i.Status,
		&i.TriggeredBy,
		&i.CommitSha,
		&i.ImageTag,
		&i.BuildLogs,
		&i.ErrorMessage,
		&i.StartedAt,
		&i.BuildStartedAt,
		&i.BuildEndedAt,
		&i.DeployStartedAt,
		&i.FinishedAt,
		&i.IdempotencyKey,
		&i.HealthStatus,
		&i.HealthMessage,
		&i.HealthCheckedAt,
	)
	return i, err
}
